fn arccos(x: Vec<i8>) -> Vec<i8> {
    // We know each element of `x` is in [-1, 1].
    // We map:
    //   -1 -> 3
    //    1 -> 0
    //    0 -> 2  (any value in [0,3] is valid for 0; here we choose 2)
    //
    // We preserve the length and positional correspondence.

    x.into_iter()
     .map(|v| match v {
         -1 => 3,
          0 => 2,
          1 => 0,
          _ => panic!("Input element out of range [-1, 1]: {}", v),
     })
     .collect()
}

